// Plan:
// 1. Check if the input array is empty.
// 2. If empty, return null.
// 3. Initialize min and max with the first element of the array.
// 4. Iterate through the array, updating min and max as needed.
// 5. Return the array [min, max].

use serde_json::Value;

pub fn solve(input: Value) -> Value {
    // Check if the input is an array
    if let Value::Array(arr) = input {
        // Check if the array is empty
        if arr.is_empty() {
            return Value::Null;
        }

        // Initialize min and max with the first element
        let mut min = arr[0].as_i64().unwrap();
        let mut max = arr[0].as_i64().unwrap();

        // Iterate through the array to find min and max
        for num in arr.iter() {
            if let Some(n) = num.as_i64() {
                if n < min {
                    min = n;
                }
                if n > max {
                    max = n;
                }
            }
        }

        // Return the array [min, max]
        Value::Array(vec![Value::Number(min.into()), Value::Number(max.into())])
    } else {
        // If the input is not an array, return null
        Value::Null
    }
}
